#!/usr/bin/env python3
"""Grader for agent-rpg hard difficulty benchmark task."""

import json
import os
import sys
import hashlib
from pathlib import Path

# Required markers that must be detected in the output
REQUIRED_MARKERS = [
    "MARKER_CAMPAIGN_BRIEF",
    "MARKER_MAP_PAGE_1",
    "NPC_MORROW_NOTE"
]

# Expected factions from input files
EXPECTED_FACTIONS = ["Chrome Veil", "Ash Choir"]

# Expected NPC with specific attributes
EXPECTED_NPCS = {
    "Morrow": {
        "secret": "pact ledger destroyed"
    }
}

def load_output():
    """Load the session package from workspace."""
    output_path = Path("workspace/session_package.json")
    if not output_path.exists():
        return None, "Output file not found: workspace/session_package.json"

    try:
        with open(output_path, 'r', encoding='utf-8') as f:
            return json.load(f), None
    except json.JSONDecodeError as e:
        return None, f"Invalid JSON in output: {e}"
    except Exception as e:
        return None, f"Error reading output: {e}"

def check_markers(output):
    """Check that all required markers are detected in output."""
    markers_found = output.get("detected_markers", [])
    missing_markers = []

    for marker in REQUIRED_MARKERS:
        if marker not in markers_found:
            missing_markers.append(marker)

    if missing_markers:
        return False, f"Missing markers in output: {missing_markers}"
    return True, f"All {len(REQUIRED_MARKERS)} markers detected"

def check_character_sheet(output):
    """Check that character sheet has valid D20 attributes."""
    character = output.get("character", {})

    if not character:
        return False, "No character sheet found in output"

    # Check for required character fields
    required_fields = ["name", "attributes"]
    missing_fields = [f for f in required_fields if f not in character]
    if missing_fields:
        return False, f"Character missing required fields: {missing_fields}"

    # Check for D20-style attributes
    attributes = character.get("attributes", {})
    d20_attrs = ["STR", "DEX", "CON", "INT", "WIS", "CHA"]
    found_d20_attrs = [attr for attr in d20_attrs if attr in attributes]

    if len(found_d20_attrs) < 3:
        return False, f"Character needs at least 3 D20 attributes, found: {found_d20_attrs}"

    # Check attributes are numeric
    for attr, val in attributes.items():
        if not isinstance(val, (int, float)):
            return False, f"Attribute {attr} must be numeric, got: {type(val)}"

    return True, f"Character sheet valid with {len(found_d20_attrs)} D20 attributes"

def check_npc_profiles(output):
    """Check that NPC profiles include expected NPCs with correct attributes."""
    npcs = output.get("npcs", [])

    if not npcs:
        return False, "No NPCs found in output"

    # Find Morrow and check secret
    morrow_found = False
    for npc in npcs:
        if isinstance(npc, dict):
            if npc.get("name", "").lower() == "morrow":
                morrow_found = True
                secret = npc.get("secret", "").lower()
                if "pact ledger" in secret and "destroy" in secret:
                    return True, "Morrow found with correct secret about pact ledger"
                return False, f"Morrow found but secret incorrect: {npc.get('secret', 'none')}"

    if not morrow_found:
        return False, "NPC Morrow not found in output"

    return True, "NPC profiles valid"

def check_factions(output):
    """Check that faction data includes expected factions."""
    factions = output.get("factions", [])

    if not factions:
        return False, "No factions found in output"

    faction_names = []
    for faction in factions:
        if isinstance(faction, dict):
            faction_names.append(faction.get("name", ""))
        else:
            faction_names.append(str(faction))

    missing_factions = []
    for expected in EXPECTED_FACTIONS:
        found = any(expected.lower() in f.lower() for f in faction_names)
        if not found:
            missing_factions.append(expected)

    if missing_factions:
        return False, f"Missing factions: {missing_factions}"

    return True, f"All {len(EXPECTED_FACTIONS)} factions found"

def check_determinism(output):
    """Check that output includes seed information for determinism."""
    metadata = output.get("metadata", {})
    seed = metadata.get("seed")

    if seed is None:
        return False, "No seed found in metadata"

    if seed != 1337:
        return False, f"Seed mismatch: expected 1337, got {seed}"

    return True, "Determinism seed (1337) correctly recorded"

def check_narrative(output):
    """Check that narrative outline is present."""
    narrative = output.get("narrative", {})

    if not narrative:
        return False, "No narrative outline found in output"

    # Check for key story elements
    narrative_str = json.dumps(narrative).lower()
    required_elements = ["pact ledger", "missing courier"]
    missing_elements = [e for e in required_elements if e not in narrative_str]

    if missing_elements:
        return False, f"Narrative missing key elements: {missing_elements}"

    return True, "Narrative outline contains required story elements"

def run_grader():
    """Run all grading checks and return results."""
    results = {
        "passed": True,
        "checks": {}
    }

    # Load output
    output, error = load_output()
    if error:
        results["passed"] = False
        results["checks"]["file_load"] = {"passed": False, "message": error}
        return results

    # Run all checks
    checks = [
        ("marker_extraction", check_markers),
        ("character_sheet", check_character_sheet),
        ("npc_profiles", check_npc_profiles),
        ("faction_data", check_factions),
        ("determinism", check_determinism),
        ("narrative", check_narrative)
    ]

    for check_name, check_func in checks:
        passed, message = check_func(output)
        results["checks"][check_name] = {"passed": passed, "message": message}
        if not passed:
            results["passed"] = False

    return results

def main():
    """Main entry point for grader."""
    results = run_grader()

    # Print results in a structured format
    print("=" * 60)
    print("AGENT-RPG BENCHMARK GRADER RESULTS")
    print("=" * 60)

    for check_name, result in results["checks"].items():
        status = "PASS" if result["passed"] else "FAIL"
        print(f"[{status}] {check_name}: {result['message']}")

    print("=" * 60)
    overall = "PASS" if results["passed"] else "FAIL"
    print(f"OVERALL: {overall}")
    print("=" * 60)

    # Exit with appropriate code
    sys.exit(0 if results["passed"] else 1)

if __name__ == "__main__":
    main()
GRADER
